import torch, copy

def loss_slice(model, loss_fn, X, y, steps=21, span=1.0):
    base = [p.detach().clone() for p in model.parameters()]
    # Two random directions, normalized per parameter tensor to match weight scale
    dirs = []
    for _ in range(2):
        d = [torch.randn_like(p) for p in base]
        d = [di * p.norm() / (di.norm() + 1e-10) for di, p in zip(d, base)]
        dirs.append(d)
    alphas = torch.linspace(-span, span, steps)
    grid = torch.zeros(steps, steps)
    with torch.no_grad():
        for i, a in enumerate(alphas):
            for j, b in enumerate(alphas):
                for p, p0, d1, d2 in zip(model.parameters(), base, *dirs):
                    p.copy_(p0 + a * d1 + b * d2)  # move along the plane
                grid[i, j] = loss_fn(model(X), y)
        for p, p0 in zip(model.parameters(), base):
            p.copy_(p0)  # restore original weights
    return alphas, grid

