import numpy as np

def neuron(x, w, b, activation="sigmoid"):
    z = np.dot(w, x) + b                  # weighted sum plus bias
    if activation == "sigmoid":
        return 1 / (1 + np.exp(-z))
    if activation == "relu":
        return np.maximum(0, z)
    return np.where(z >= 0, 1.0, 0.0)     # step function (perceptron)

# A neuron implementing logical AND
w = np.array([1.0, 1.0])
b = -1.5
for x in [(0, 0), (0, 1), (1, 0), (1, 1)]:
    print(x, neuron(np.array(x), w, b, activation="step"))

# The same weights with a sigmoid give a smooth probability
print(round(float(neuron(np.array([1, 1]), w * 5, b * 5)), 3))
